-- =============================================================================
-- NUVORA 2.0  |  20261011091200  |  Customer order confirmation token
--
-- WHY THIS EXISTS, and why it is a security fix rather than a convenience.
--
-- The gateway sends a paying customer back to /orders/{orderNumber}. Order numbers are
-- generated by a sequence (NUV-YYYYMMDD-NNNNNN starting at 1000) because a sequence cannot
-- collide and support can reason about ordering from it. That property is exactly what makes
-- it unsafe as a public lookup key: consecutive numbers are trivially guessable, so a URL
-- built from one would let anybody walk the day's orders and read other people's purchases -
-- including delivery payloads, which for an eSIM means a working activation code.
--
-- An RLS policy cannot fix this on its own. The confirmation page is reached by a GUEST:
-- checkout writes orders with user_id NULL, and every SELECT policy on orders is
-- `user_id = current_user_id()`, so a guest order matches no policy and is readable by
-- nobody. That is correct for the API and useless for the page. Widening the policy would
-- open the table; leaving it would 404 the customer who just paid.
--
-- So the confirmation page does not read the table. It presents a per-order SECRET
-- (public_token), and a SECURITY DEFINER function returns a fixed, customer-safe projection
-- for that secret and nothing else. Three consequences worth stating plainly:
--
--   * The token is the credential. 128 bits from gen_random_bytes, so it cannot be walked.
--   * The projection is a CLOSED list of columns. Cost, margin, supplier reference, internal
--     note, engine version and the raw gateway payload are not in it and cannot be requested
--     through it, so the "supplier cost never reaches a customer" rule holds on this path
--     by construction rather than by remembering to exclude a field.
--   * RLS stays exactly as it was. No policy is widened, and anon still cannot SELECT from
--     orders directly.
--
-- The function is callable by anon because the caller has no session. It takes no order id
-- and no email, so it cannot be used to probe for either: a guess returns null.
-- =============================================================================

create extension if not exists pgcrypto;

-- -----------------------------------------------------------------------------
-- The token column
-- -----------------------------------------------------------------------------
alter table public.orders
  add column if not exists public_token text;

-- Backfill before NOT NULL. gen_random_bytes is 128 bits of entropy; the unique index below
-- makes a collision impossible rather than merely unlikely.
update public.orders
   set public_token = encode(gen_random_bytes(16), 'hex')
 where public_token is null;

alter table public.orders
  alter column public_token set not null;

alter table public.orders
  alter column public_token set default encode(gen_random_bytes(16), 'hex');

do $$
begin
  if not exists (
    select 1 from pg_constraint
     where conname = 'orders_public_token_key'
       and conrelid = 'public.orders'::regclass
  ) then
    alter table public.orders
      add constraint orders_public_token_key unique (public_token);
  end if;
end $$;

comment on column public.orders.public_token is
  'Per-order secret for the customer confirmation page. The credential for get_order_for_customer(); never exposed in any list or admin view, and never used in place of an id.';

-- No client role may read the token: reading it would let a caller fetch any order by id
-- and then present the token. Only the service role (which mints the callback URL) and the
-- SECURITY DEFINER function below may see it.
revoke select on public.orders from anon, authenticated;
grant select (
  id, order_number, user_id, email, billing_country, status, currency,
  subtotal_minor, discount_minor, tax_minor, total_minor,
  paid_at, fulfilled_at, cancelled_at, refunded_at, created_at, updated_at
) on public.orders to authenticated;

-- -----------------------------------------------------------------------------
-- The customer-safe projection
-- -----------------------------------------------------------------------------
create or replace function public.get_order_for_customer(p_token text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order    public.orders;
  v_items    jsonb;
  v_payment  jsonb;
begin
  -- Reject anything too short to be a token before touching the table, so a malformed or
  -- empty value cannot become a full-table scan.
  if p_token is null or length(p_token) < 32 then
    return null;
  end if;

  select * into v_order from public.orders where public_token = p_token;

  if not found then
    return null;
  end if;

  -- Customer-visible line data only. unit_cost_minor, supplier_reference and
  -- fulfilment_error are deliberately absent: the first two are commercially sensitive and
  -- the third is an integration detail, not something a buyer can act on.
  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'product_name',      oi.product_name,
               'product_line',      oi.product_line,
               'quantity',          oi.quantity,
               'unit_price_minor',  oi.unit_price_minor,
               'line_total_minor',  oi.line_total_minor,
               'fulfilment_status', oi.fulfilment_status,
               'delivered_at',      oi.delivered_at,
               -- The goods themselves. This is the reason the token has to be unguessable.
               'delivery_payload',  oi.delivery_payload
             )
             order by oi.created_at
           ),
           '[]'::jsonb
         )
    into v_items
    from public.order_items oi
   where oi.order_id = v_order.id;

  -- The latest attempt only, and only the fields a buyer would recognise from their bank
  -- statement. raw_payload, failure_reason and the provider transaction id stay server-side.
  select jsonb_build_object(
           'provider',    p.provider,
           'status',      p.status,
           'amount_minor', p.amount_minor,
           'currency',    p.currency,
           'verified_at', p.verified_at
         )
    into v_payment
    from public.payments p
   where p.order_id = v_order.id
   order by p.created_at desc
   limit 1;

  return jsonb_build_object(
    'order_number',  v_order.order_number,
    -- Masked on purpose. The buyer knows their own address; the mask is enough to confirm
    -- "this is my order" without turning a leaked link into a leaked contact detail.
    'email_masked',  regexp_replace(v_order.email::text, '^(.).*?(@.*)$', '\1***\2'),
    'status',        v_order.status,
    'currency',      v_order.currency,
    'subtotal_minor', v_order.subtotal_minor,
    'discount_minor', v_order.discount_minor,
    'tax_minor',     v_order.tax_minor,
    'total_minor',   v_order.total_minor,
    'created_at',    v_order.created_at,
    'paid_at',       v_order.paid_at,
    'fulfilled_at',  v_order.fulfilled_at,
    'cancelled_at',  v_order.cancelled_at,
    'refunded_at',   v_order.refunded_at,
    'items',         v_items,
    'payment',       v_payment
  );
end;
$$;

comment on function public.get_order_for_customer(text) is
  'Returns a customer-safe projection of one order for a matching public_token, or null. The only read path for the confirmation page, and the only place delivery payloads reach a browser.';

-- Replace the blanket grant with execute-only. The function is the whole surface; the table
-- underneath stays closed to anon.
revoke all on function public.get_order_for_customer(text) from public;
grant execute on function public.get_order_for_customer(text) to anon, authenticated;
grant execute on function public.get_order_for_customer(text) to service_role;
